mapper.select:
select
a.region_id,
a.region_name,
a.sort,
a.device_type,
a.up_region_id,
a.up_region_ids,
a.region_type,
a.station_id,
a.state,
a.create_time
from t_robot_region a
where 1 = 1
 and a.region_id = #{regionId, jdbcType=VARCHAR}
 and a.region_name = #{regionName, jdbcType=VARCHAR}
 and a.sort = #{sort, jdbcType=INTEGER}
 and a.device_type = #{deviceType, jdbcType=VARCHAR}
 and a.up_region_id = #{upRegionId, jdbcType=VARCHAR}
 and a.up_region_ids = #{upRegionIds, jdbcType=VARCHAR}
 and a.region_type = #{regionType, jdbcType=INTEGER}
 and a.station_id = #{stationId, jdbcType=VARCHAR}
 and a.state = #{state, jdbcType=INTEGER}
 and a.create_time = #{createTime, jdbcType=TIMESTAMP}

